import { Button, Menu, MenuItem } from '@mui/material'
import type { MouseEvent } from 'react'
import { useCallback, useState } from 'react'
import { projectSessionService, type ProjectFolderValues } from '../../services/project/project_session_service'
import { BranchSwitchDialog } from './project/branch_switch_dialog'
import { CompleteReleaseDialog } from './project/complete_release_dialog'
import { NewCardDialog } from './project/new_card_dialog'
import { ProjectOpenDialog } from './project/project_open_dialog'
import { useProjectToolbarMenuActions } from './project/use_project_toolbar_menu_actions'
import { useProjectPersistence } from '../hooks/use_project_persistence'
import { useProjectReadOnly } from '../hooks/use_project_read_only'

type ProjectDialogMode = 'open' | 'branch' | 'card' | 'release'

interface ProjectToolbarMenuProps {
    accessToken: string | null
    isGithubAuthenticated: boolean
}

/** Toolbar project menu with dialogs for project session commands. */
export function ProjectToolbarMenu(props: ProjectToolbarMenuProps) {
    const { accessToken, isGithubAuthenticated } = props
    const [anchorElement, setAnchorElement] = useState<HTMLElement | null>(null)
    const [dialogMode, setDialogMode] = useState<ProjectDialogMode | null>(null)
    const { hasPendingPush, hasPendingSave } = useProjectPersistence()
    const readOnly = useProjectReadOnly()
    const isMenuOpen = !!anchorElement

    const openDialog = useCallback((mode: ProjectDialogMode) => {
        setAnchorElement(null)
        setDialogMode(mode)
        projectSessionService.setError(null)
    }, [])

    const handleCloseDialogState = useCallback(() => {
        setDialogMode(null)
    }, [])
    const actions = useProjectToolbarMenuActions({
        accessToken,
        isGithubAuthenticated,
        onCloseDialog: handleCloseDialogState,
        onOpenDialog: openDialog,
    })

    const handleProjectButtonClick = (event: MouseEvent<HTMLButtonElement>) => setAnchorElement(event.currentTarget)
    const handleCloseMenu = () => setAnchorElement(null)
    const handleOpenProject = () => {
        setAnchorElement(null)
        actions.openProjectDialog()
    }
    const handlePushClick = async () => {
        setAnchorElement(null)
        try {
            await actions.push()
        } catch {
            // ProjectSessionService emits the user-visible error.
        }
    }
    const handleOpenReleaseDialog = () => {
        void actions.openReleaseDialog()
    }
    const handleOpenCardDialog = () => actions.openNewCardDialog()
    const handleConfirmProjectFolderSetup = (values: ProjectFolderValues) => {
        void actions.confirmProjectFolderSetup(values)
    }
    const handleDiscardGithubPendingCommits = () => {
        if (!actions.pendingGithubConflictProject) return

        projectSessionService.discardGithubPendingCommits(actions.pendingGithubConflictProject, accessToken)
    }

    return (
        <>
            <Button aria-controls={isMenuOpen ? 'project-menu' : undefined} aria-haspopup="true" onClick={handleProjectButtonClick} size="small" variant="outlined">
                Project
            </Button>
            <Menu anchorEl={anchorElement} id="project-menu" onClose={handleCloseMenu} open={isMenuOpen}>
                <MenuItem onClick={handleOpenProject}>Open project...</MenuItem>
                {actions.isProjectOpen ? <MenuItem onClick={actions.openBranchDialog}>Switch branch...</MenuItem> : null}
                {actions.isProjectOpen && actions.pushMode === 'manual' ? (
                    <MenuItem
                        disabled={readOnly || actions.isLoading || (!hasPendingPush && !hasPendingSave)}
                        onClick={handlePushClick}
                    >
                        Push
                    </MenuItem>
                ) : null}
                {actions.isProjectOpen ? (
                    <MenuItem
                        disabled={readOnly || actions.isReleaseCompleting || actions.activeCardCount === 0}
                        onClick={handleOpenReleaseDialog}
                    >
                        Complete release...
                    </MenuItem>
                ) : null}
                {actions.isProjectOpen ? <MenuItem disabled={readOnly} onClick={handleOpenCardDialog}>New card...</MenuItem> : null}
            </Menu>
            <ProjectOpenDialog
                branches={actions.branches}
                initialRemoteProject={actions.initialRemoteProject}
                initialSource={actions.initialProjectSource}
                isDesktopMode={actions.isDesktopMode}
                isGithubAuthenticated={isGithubAuthenticated}
                isLoading={actions.isLoading}
                onBrowseProjectSubFolder={actions.isDesktopMode ? actions.browseProjectSubFolder : null}
                onChooseLocalFolder={actions.chooseLocalProjectFolder}
                onConfirmProjectFolderSetup={handleConfirmProjectFolderSetup}
                projectOpenResolution={actions.projectOpenResolution}
                onBranchChange={() => undefined}
                onClose={actions.closeDialog}
                onCreateRemoteProject={actions.createRemoteProject}
                onDiscardGithubPendingCommits={handleDiscardGithubPendingCommits}
                onLoadManualBranches={actions.loadManualBranches}
                onLoadRemoteBranches={actions.loadRemoteBranches}
                onOpenGithub={actions.openGithubProject}
                onOpenLocal={actions.openLocalProject}
                onOpenRemote={actions.openRemoteProject}
                onRemoveRecentLocal={actions.removeRecentLocalProject}
                onRepositoryChange={actions.loadRepositoryBranches}
                onSourceChange={actions.clearOpenDialogState}
                open={dialogMode === 'open'}
                pendingGithubConflictProject={actions.pendingGithubConflictProject}
                recentLocalRepositories={actions.recentLocalRepositories}
                repositories={actions.repositories}
            />
            <BranchSwitchDialog
                branches={actions.branches}
                isLoading={actions.isLoading}
                onBranchChange={actions.setSwitchBranch}
                onClose={actions.closeDialog}
                onSwitchBranch={(branch) => void actions.switchProjectBranch(branch)}
                open={dialogMode === 'branch'}
                selectedBranch={actions.switchBranch}
            />
            <CompleteReleaseDialog
                branchCandidates={actions.releaseBranchCandidates}
                defaultSelectAll={actions.releaseSelectAllDefault}
                isLoading={actions.isLoading}
                key={dialogMode === 'release' ? 'release-open' : 'release-closed'}
                onClose={actions.closeDialog}
                onCompleteRelease={actions.completeRelease}
                onSelectAllDefaultChange={actions.setReleaseSelectAllDefault}
                open={dialogMode === 'release'}
            />
            <NewCardDialog
                cardTypes={actions.cardTypes}
                initialTargetStatus={actions.newCardInitialStatus}
                isLoading={actions.isLoading}
                isProjectOpen={actions.isProjectOpen}
                onClose={actions.closeDialog}
                onCreateCard={actions.createCard}
                open={dialogMode === 'card'}
                states={actions.states}
            />
        </>
    )
}

    const handleTabChange = (value: string) => {
        setCurrentTab(value as AppMenuTab)
    }

    const handleOpenProject = () => {
        actions.openProjectDialog()
    }

    const handleConfirmProjectFolderSetup = (values: ProjectFolderValues) => {
        void actions.confirmProjectFolderSetup(values)
    }

    const handleLoadBranches = () => {
        void actions.loadSwitchBranches()
    }

    const handleBranchChange = (event: SelectChangeEvent) => {
        void actions.switchProjectBranch(event.target.value)
    }

    const handleImportSentryIssues = () => {
        void sentryImportService.importNow()
    }

    const handleOpenReleaseDialog = () => {
        void actions.openReleaseDialog()
    }

    const handleOpenCardDialog = () => {
        actions.openNewCardDialog()
    }

    const handleOpenActiveSchedules = () => {
                            onClick={handleOpenReleaseDialog}                            <CheckCircleOutline fontSize="small" />                        </MenuIconButton>                        {canShowSentryImport ? (                            <MenuIconButton                                disabled={readOnly || sentryImport.isPolling}                                label="Import Sentry issues"                                onClick={handleImportSentryIssues}                                tooltip={sentryImport.isPolling ? 'Checking Sentry...' : 'Import Sentry issues'}
                            >                                <BugOutline fontSize="small" />                            </MenuIconButton>                        ) : null}                    </Section>                    onOpenGithub={actions.openGithubProject}                    onOpenRemote={actions.openRemoteProject}
                    onRemoveRecentLocal={actions.removeRecentLocalProject}                    onRepositoryChange={actions.loadRepositoryBranches}                    onSourceChange={actions.clearOpenDialogState}                    open
                    pendingGithubConflictProject={actions.pendingGithubConflictProject}                    recentLocalRepositories={actions.recentLocalRepositories}                    repositories={actions.repositories}                />            ) : null}            {dialogMode === 'schedules' ? (                <ActiveSchedulesDialog                    onClose={closeDialog}




                    open
                    states={actions.states}
                />
            ) : null}
        </Menu>
    )

    return (
        <AppBar
            color="default"
            elevation={0}
            position="static"
            sx={{ borderBottom: 1, borderColor: 'divider', bgcolor: 'background.paper' }}
        >
            <MainToolbar
                availableTabs={availableMenuTabs}
                currentTab={visibleCurrentTab}
                isMobile={isMobile}
                isNewActionDisabled={!project || readOnly}
                isNewCardDisabled={!actions.isProjectOpen || readOnly}
                isNewDiagramDisabled={!actions.isProjectOpen || readOnly || isCreatingDiagram}
                onCreateAction={handleCreateAction}
                onCreateCard={handleOpenCardDialog}
                onCreateDiagram={handleCreateDiagram}
                onOpenMenu={onOpenMobileMenu}
                onTabChange={handleTabChange}
                regexpAgent={regexpAgent}
            />
            <Box style={NO_DRAG_REGION}>{menuPanel}</Box>
        </AppBar>
    )
}

import { useCallback, useEffect, useMemo, useState } from 'react'
import {
    DEFAULT_CARD_TYPES,
    DEFAULT_STATES,
    type BranchReference,
    type CardDraft,
    type ProjectReference,
    type PushMode,
    type ReleaseBranchCandidate,
    type RepositoryReference,
} from '../../../data/data_types'
} from '../../../data/recent_local_repositories'    projectSessionService,    OPEN_NEW_CARD_DIALOG_EVENT,
    OPEN_PROJECT_DIALOG_EVENT,
    type OpenNewCardDialogDetail,
    type OpenProjectDialogDetail,
    type ProjectDialogSource,
} from '../../project_command_events'

type ProjectDialogMode = 'open' | 'branch' | 'card' | 'release'
type ProjectOpenResult = 'failed' | 'opened' | 'resolution'

const EMPTY_BRANCHES: BranchReference[] = []
const EMPTY_REPOSITORIES: RepositoryReference[] = []

interface UseProjectToolbarMenuActionsArgs {
    accessToken: string | null
    initialProjectOpenResolution?: ProjectOpenResolution | null
    isGithubAuthenticated: boolean    const [projectOpenResolution, setProjectOpenResolution] = useState<ProjectOpenResolution | null>(initialProjectOpenResolution)
    const [initialProjectSource, setInitialProjectSource] = useState<ProjectDialogSource | null>(
        initialProjectOpenResolution?.storageType === 'remote' ? 'remote' : null,
    )
    const [initialRemoteProject, setInitialRemoteProject] = useState<ProjectReference | null>(
        initialProjectOpenResolution?.storageType === 'remote' ? initialProjectOpenResolution.project : null,
    )
    const [newCardInitialStatus, setNewCardInitialStatus] = useState('')
    const [pendingLocalRootPath, setPendingLocalRootPath] = useState<string | null>(null)
    const [recentLocalRepositories, setRecentLocalRepositories] = useState(() => readRecentLocalRepositories())            if (resolution) {
            return 'failed'
        } catch (error) {

        }            const detail = (event as CustomEvent<OpenProjectDialogDetail>).detail
            setInitialProjectSource(detail?.source ?? null)
            setInitialRemoteProject(detail?.project ?? null)
            setProjectOpenResolution(detail?.resolution ?? null)
            onOpenDialog('open')
            if (isGithubAuthenticated) void loadRepositories()
        }

        window.addEventListener(OPEN_PROJECT_DIALOG_EVENT, handleOpenProjectDialog)

        return () => window.removeEventListener(OPEN_PROJECT_DIALOG_EVENT, handleOpenProjectDialog)
    }, [isGithubAuthenticated, loadRepositories, onOpenDialog])

    useEffect(() => {
        const handleOpenNewCardDialog = (event: Event) => {
            if (!project) return

            const { status } = (event as CustomEvent<OpenNewCardDialogDetail>).detail
            const initialStatus = states.some((stateConfig) => stateConfig.state === status) ? status : states[0]?.state
            setNewCardInitialStatus(initialStatus ?? '')
            onOpenDialog('card')
        }

        window.addEventListener(OPEN_NEW_CARD_DIALOG_EVENT, handleOpenNewCardDialog)

        return () => window.removeEventListener(OPEN_NEW_CARD_DIALOG_EVENT, handleOpenNewCardDialog)
    }, [onOpenDialog, project, states])

    const openNewCardDialog = () => {
        setNewCardInitialStatus(states[0]?.state ?? '')
        onOpenDialog('card')
    }

    const openProjectDialog = () => {
        setInitialProjectSource(null)
        setInitialRemoteProject(null)

        onOpenDialog('open')
        if (isGithubAuthenticated) void loadRepositories()
    }

    const openBranchDialog = () => {
        onOpenDialog('branch')
        void loadSwitchBranches()
    }

    const clearOpenDialogState = () => {
        setBranches(EMPTY_BRANCHES)
        setProjectOpenResolution(null)
    }

    const loadRepositoryBranches = async (repository: RepositoryReference) => {
        try {
            const nextBranches = await projectSessionService.listBranches('github', repository, accessToken)
            setBranches(nextBranches)

            return nextBranches
        } catch {
            setBranches(EMPTY_BRANCHES)

            return EMPTY_BRANCHES
        }
    }

    const loadManualBranches = async (owner: string, repositoryName: string, isPublic: boolean) => {
        try {
            const storageType = isPublic ? 'github-readonly' : 'github'
            const result = await projectSessionService.findGithubRepositoryBranches(owner, repositoryName, accessToken, storageType)
            setBranches(result.branches)

            return result
        } catch {
            return null
        }
    }

    const createRemoteProject = (rootPath: string, branch: string): ProjectReference | null => {
        try {
            if (rootPath.length === 0) throw new Error('Missing remote project root path')

            return { branch: branch || 'main', id: rootPath, rootPath }
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Remote project could not be created' })

            return null
        }
    }

    const loadRemoteBranches = async (endpoint: string, rootPath: string, branch: string) => {
        const remoteProject = createRemoteProject(rootPath, branch)
        if (!remoteProject) {
            setBranches(EMPTY_BRANCHES)

            return EMPTY_BRANCHES
        }

        projectSessionService.configureRemote(endpoint)

        try {
            const nextBranches = await projectSessionService.listBranches('remote', remoteProject, accessToken)
            setBranches(nextBranches)

            return nextBranches
        } catch {
            setBranches(EMPTY_BRANCHES)

            return EMPTY_BRANCHES
        }
    }

    const openGithubProject = async (owner: string, repositoryName: string, branch: string, isPublic: boolean) => {
        try {
            const storageType = isPublic ? 'github-readonly' : 'github'
            const result = await projectSessionService.findGithubRepositoryBranches(owner, repositoryName, accessToken, storageType)
            const fallbackBranches = branches.length > 0 ? branches : result.branches
            const selectedBranch = branch || branchValue(fallbackBranches, result.repository.branch)
            setBranches(fallbackBranches)
            await openProject(storageType, { ...result.repository, branch: selectedBranch })
        } catch {
            // ProjectSessionService emits the user-visible error.
        }
    }

    const openRemoteProject = async (endpoint: string, nextProject: ProjectReference) => {
        projectSessionService.configureRemote(endpoint)
        await openProject('remote', nextProject)
    }

    const confirmProjectFolderSetup = async (values: ProjectFolderValues) => {
        if (!projectOpenResolution) return

        const resolution = projectOpenResolution
        beginProjectLoad()
        try {
            await projectSessionService.confirmProjectFolderSetup(resolution, values, accessToken)
            if (pendingLocalRootPath) await recordOpenedLocalProject(pendingLocalRootPath)
        } catch {
            // ProjectSessionService emits the user-visible error.
        }
    }

    /**
     * Opens the OS directory dialog for one folder field and returns the picked folder relative to
     * the repository root, or relative to the project folder for the four sub-folders. A pick
     * outside the repository is a user mistake, so it is shown and not reported.
     */
    const browseProjectSubFolder = async (_currentValue: string, projectFolder: string, isProjectFolder: boolean) => {
        const rootPath = projectOpenResolution?.project.rootPath
        if (!electronBridge?.selectProjectSubFolder || !rootPath) return null

        const picked = await electronBridge.selectProjectSubFolder(rootPath)
        if (picked === null) return null

        const repositoryRelativePath = toRepositoryRelativePath(rootPath, picked)
        if (repositoryRelativePath === null || repositoryRelativePath.length === 0) {
            dialogService.displayError('Choose a folder inside the repository.')

            return null
        }
        if (isProjectFolder) return repositoryRelativePath

        const projectFolderRelativePath = toProjectFolderRelativePath(projectFolder, repositoryRelativePath)
        if (projectFolderRelativePath === null || projectFolderRelativePath.length === 0) {
            dialogService.displayError(`Choose a folder inside '${projectFolder}'.`)

            return null
        }

        return projectFolderRelativePath
    }

    const switchProjectBranch = async (branch: string) => {
        try {
            await projectSessionService.switchBranch(branch)
            closeDialog()
        } catch {
            // ProjectSessionService emits the user-visible error.
        }
    }

    const openReleaseDialog = async () => {
        try {
            setReleaseBranchCandidates(await projectSessionService.getReleaseBranchCandidates())
            onOpenDialog('release')
        } catch {
            // ProjectSessionService emits the user-visible error.
        }
    }

    const completeRelease = async (releaseName: string, selectedBranchNames: string[]) => {
        setIsReleaseCompleting(true)
        try {
            await projectSessionService.completeRelease(releaseName, selectedBranchNames)
            closeDialog()
        } catch {
            // ProjectSessionService emits the user-visible error.
        } finally {
            setIsReleaseCompleting(false)
        }
    }

    const setReleaseSelectAllDefault = (selected: boolean) => {
        void configService.setProjectPreference('project.deleteBranchesAfterRelease', selected)
    }

    const createCard = async (draft: CardDraft, initialState: string) => {
        await projectSessionService.createCard(draft, initialState)
        closeDialog()
    }

    return {
        activeCardCount,
        branches,
        cardTypes,
        chooseLocalProjectFolder,
        clearOpenDialogState,
        closeDialog,
        commit: () => projectSessionService.commit(),
        completeRelease,
        initialProjectSource,
        initialRemoteProject,
        newCardInitialStatus,
        browseProjectSubFolder,
        confirmProjectFolderSetup,
        createCard,
        createRemoteProject,
        isLoading: projectSession.isLoading,
        isDesktopMode: !!electronBridge,
        isProjectOpen: !!project,
        isReleaseCompleting,
        loadSwitchBranches,
        loadManualBranches,
        loadRemoteBranches,
        loadRepositoryBranches,
        projectOpenResolution,
        openBranchDialog,
        openGithubProject,
        openLocalProject,
        openNewCardDialog,
        openProjectDialog,
        openRemoteProject,
        openReleaseDialog,
        pendingGithubConflictProject: projectSession.pendingGithubConflictProject,
        pull: () => projectSessionService.pull(),
        push: () => projectSessionService.push(),
        pushMode,
        recentLocalRepositories,
        removeRecentLocalProject,
        repositories,
        releaseBranchCandidates,
        releaseSelectAllDefault,
        setReleaseSelectAllDefault,
        setSwitchBranch,
        states,
        switchBranch,
        switchProjectBranch,
    }
}

